import java.io.*;
import java.util.*;

public class E {
    public static void main(String[] args) throws Exception {
        new E().start();
    }

    public void start() throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();

        if (n % 2 == 1 && m % 2 == 1) {
            long val = pow(pow(r - l + 1, n), m);
            pw.println(val);
            pw.flush();
            return;
        }

        int evenCount = r / 2 - (l + 1) / 2 + 1;
        int oddCount = (r - l + 1) - evenCount;

        long[][] matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
        matrix = matrixExponentiation(matrix, n);
        matrix = matrixExponentiation(matrix, m);
        pw.println(matrix[0][0]);
        pw.flush();
    }

    final int MOD = 998244353;

    long[][] multiply(long[][] a, long[][] b) {
        int rA = a.length, cA = a[0].length;
        int rB = b.length, cB = b[0].length;
        long[][] res = new long[rA][cB];
        for (int i = 0; i < rA; i++) {
            for (int j = 0; j < cB; j++) {
                long sum = 0;
                for (int k = 0; k < cA; k++) {
                    sum += a[i][k] * b[k][j];
                }
                res[i][j] = sum % MOD;
            }
        }
        return res;
    }

    long[][] matrixExponentiation(long[][] base, int exp) {
        if (exp == 1) return base;
        long[][] half = matrixExponentiation(base, exp / 2);
        long[][] result = multiply(half, half);
        if (exp % 2 == 1) {
            result = multiply(result, base);
        }
        return result;
    }

    long pow(long base, int exp) {
        long res = 1;
        long cur = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                res = (res * cur) % MOD;
            }
            cur = (cur * cur) % MOD;
            e >>= 1;
        }
        return res;
    }
}
